// Original synthesis dossiers, with supplied assumptions and explained distinctions.
import {course,point} from './course-builder.mjs';
import {SOURCES as S} from './content-authoring.mjs';
const d=(title,intro,method,concepts,context,questions,sources)=>({title,intro,method,concepts,context,questions,sources});
export const SYNTHESIS_DATA={
UE1:d('Dossier de synthèse : validité, inexécution et réparation',
'Une même difficulté contractuelle peut conduire à des demandes différentes. Ce dossier apprend à choisir la question utile avant de parler de sanction : validité de l’engagement, exécution d’une obligation ou réparation d’un préjudice. La chronologie et les preuves empêchent de tout traiter comme une annulation automatique.',
'Séparez formation et exécution. Qualifiez la demande, relevez ses conditions et rattachez chacune à un fait démontré.',[
['Validité','La nullité répond à un défaut affectant les conditions de validité du contrat.','Elle ne se déduit pas simplement d’un retard dans l’exécution. Repérez le défaut allégué au moment de la formation. L’article 1178 prévoit une nullité prononcée par le juge ou constatée d’un commun accord. Les conséquences sur les prestations doivent être examinées distinctement, sans décider leur montant à partir d’un seul mot.'],
['Inexécution','La résolution concerne l’inexécution et ses conditions propres.','L’article 1224 distingue la clause résolutoire, la notification en cas d’inexécution suffisamment grave et la décision de justice. Une prestation décevante ne démontre pas automatiquement que toutes les conditions sont satisfaites. Indiquez la voie envisagée et les vérifications utiles ; ne confondez pas ce contrôle avec celui de la validité initiale.'],
['Demande chiffrée','Une réparation doit être reliée à un préjudice établi et au régime pertinent.','Distinguez le fait générateur, le dommage et son évaluation. Une demande de 2 000 € n’est pas une preuve de 2 000 € de préjudice. La pièce disponible peut établir une dépense précise sans établir les autres sommes invoquées. La conclusion doit conserver ces limites et le lien avec l’obligation concernée.'],
['Conclusion conditionnelle','Une information manquante doit conduire à préciser le contrôle restant.','Écrire une réserve utile consiste à nommer ce qui manque et pourquoi cela compte. Une conclusion conditionnelle n’est pas une absence de réponse : elle indique ce que les faits permettent d’établir. Évitez aussi de cumuler des sanctions sans vérifier leur fondement, leurs effets et les demandes effectivement formulées.']],
'Un contrat est présenté comme valablement formé. Le fournisseur livre avec retard. Le client demande « la nullité » et 2 000 € ; une pièce justifie 300 € de dépenses, mais les conditions d’une résolution ne sont pas documentées.',[
['Quelle distinction faire avant de répondre ?','Le retard relève de l’exécution. Aucun défaut de formation n’est donné ; il faut distinguer validité, inexécution et éventuelle réparation.'],
['Peut-on affirmer une résolution déjà acquise ?','Non. La voie, la gravité et les conditions pertinentes restent à examiner. Le dossier ne permet pas de les tenir pour établies.'],
['Que prouvent les montants donnés ?','La demande de 2 000 € exprime une prétention. La pièce documente 300 € de dépenses, sans démontrer seule toutes les conditions de responsabilité ni le montant total réparable.']],[S.civil]),
UE2:d('Dossier de synthèse : financement et engagements personnels',
'Le financement d’une société associe parfois apport, prêt d’associé et garantie personnelle. Ces opérations peuvent concerner la même personne, mais elles ne donnent pas les mêmes droits. L’analyse doit identifier le patrimoine engagé et conserver la trace des décisions et des contrats.',
'Dressez un tableau personne, qualité, flux, droit et document. Analysez ensuite les pouvoirs de signature séparément du financement.',[
['Apport','Un apport finance la société et se distingue du chiffre d’affaires.','Une entrée en banque peut venir d’un apport, d’un prêt ou d’une vente. Sa qualification dépend de l’opération, pas de la seule variation de trésorerie. Vérifiez les documents de souscription et les décisions pertinentes. Le capital annoncé et le montant réellement libéré doivent être décrits sans les supposer égaux dans tous les dossiers.'],
['Prêt d’associé','Un prêt d’associé crée une relation de créancier distincte des titres.','Le prêteur peut aussi posséder des droits sociaux, mais le remboursement du prêt ne se confond pas avec un dividende. Relevez les conditions de remboursement et les restrictions éventuelles dans les documents. Ne supposez pas une disponibilité immédiate du solde lorsque le dossier ne précise pas ces conditions.'],
['Garantie','Une caution personnelle doit être analysée comme un engagement distinct.','La forme sociale ne suffit pas à neutraliser une garantie volontaire. Identifiez le garant, le bénéficiaire, le montant et les conditions de l’engagement, sans inventer une clause. La dette sociale et la garantie doivent rester séparées dans le tableau des risques, même lorsqu’une personne cumule plusieurs qualités.'],
['Signature','La détention de titres ne démontre pas seule un pouvoir de représentation.','Examinez qualité, mandat et régime applicable. Le fait de financer la société ne prouve pas qu’une personne peut conclure tout contrat en son nom. Rattachez chaque signature à son objet : souscription, prêt, garantie ou engagement social. Cette séparation évite de déplacer une dette d’un patrimoine à un autre sans fondement.']],
'Maya verse 12 000 € d’apport et prête 8 000 € à la société. Elle signe séparément une caution de 5 000 €. Le gérant conclut le contrat bancaire au nom de la société ; ses pouvoirs sont à vérifier.',[
['Classez les deux versements de Maya.','12 000 € correspondent à un apport ; 8 000 € à un prêt distinct. Aucun des deux versements ne constitue une vente de l’activité.'],
['La caution se confond-elle avec les droits sociaux ?','Non. Les 5 000 € désignent un engagement personnel distinct, dont il faut examiner les conditions.'],
['Quels documents relier aux engagements ?','Pièces d’apport, convention de prêt, acte de caution et documents établissant les pouvoirs du gérant.']],[S.company,S.civil]),
UE3:d('Dossier de synthèse : reconstruire une chronologie sociale',
'Un conflit social contient souvent des faits, des demandes et des interprétations mélangés. Ce dossier travaille leur séparation. La chronologie permet de relier chaque pièce à une affirmation, puis de préciser le cadre à vérifier sans prédire l’issue d’un litige.',
'Classez événements et documents. Distinguez faits constatés, demandes, réponses et hypothèses ; vérifiez le cadre avant de conclure.',[
['Fait documenté','Une pièce doit être reliée au fait précis qu’elle permet d’établir.','Un échange peut dater une demande sans démontrer l’accord de l’autre personne. Un bulletin renseigne la rémunération versée, sans expliquer seul le fondement d’une modification. Relevez contenu, date et auteur. Cette lecture évite de transformer une pièce utile en preuve de toutes les affirmations du dossier.'],
['Qualification','La qualification d’un changement précède l’analyse de ses conséquences.','Décrivez ce qui change réellement : fonctions, rémunération, horaires ou autre élément. Le titre donné par une partie ne remplace pas l’analyse. Comparez les situations et le cadre applicable, puis indiquez les conditions à vérifier. L’intérêt économique invoqué ne permet pas de supposer que toutes les démarches nécessaires ont été réalisées.'],
['Demande et accord','Une proposition ou une demande ne démontre pas un accord déjà donné.','Repérez les réponses et les conditions auxquelles elles sont éventuellement assorties. Le silence, une réponse partielle et une acceptation explicite ne doivent pas être déclarés équivalents par principe. Quand le dossier ne permet pas de conclure, nommez l’information nécessaire plutôt que d’inventer un consentement ou un refus.'],
['Litige','La conclusion doit distinguer argument établi et vérification nécessaire.','Un dossier incomplet peut soutenir une démarche documentaire, sans autoriser une prédiction certaine du jugement. Exposez les arguments dans leur ordre et indiquez les éléments qui les étayent. Une position motivée ne devient pas une décision juridictionnelle. La qualité de la réponse tient aussi à la précision de ses réserves.']],
'Un employeur annonce un changement de fonctions lundi. La salariée demande des précisions mardi. Un bulletin suivant présente une rémunération différente. Aucun avenant ni réponse définitive n’est fourni.',[
['Que permet d’établir l’échange du mardi ?','Il établit une demande de précisions, sans démontrer seul un accord sur les fonctions ou la rémunération.'],
['Que faut-il comparer ?','Les fonctions et rémunérations avant et après, les documents contractuels et le cadre applicable à la modification.'],
['Quelle conclusion éviter ?','Affirmer une acceptation ou une illégalité certaine sans avoir qualifié le changement et vérifié les conditions pertinentes.']],[['Droit du travail, ministère du Travail','https://travail-emploi.gouv.fr/droit-du-travail']]),
UE4:d('Dossier de synthèse : lire un avoir et contrôler la TVA',
'Un avoir corrige une opération et doit être rattaché à la facture concernée. Le dossier utilise des hypothèses explicites pour séparer prix hors taxe, taxe et dette. Il ne dispense pas de vérifier les règles de la situation réelle ni les conditions d’une correction fiscale.',
'Retrouvez la facture, appliquez le taux fourni à la base corrigée et rapprochez HT, TVA et TTC. Distinguez correction de la facture et règlement.',[
['Référence','L’avoir doit être rapproché de l’opération qu’il corrige.','Le numéro, la date et l’objet permettent de suivre le lien documentaire. Une diminution de dette n’explique pas seule pourquoi la base de taxe change. Vérifiez que la correction porte bien sur l’opération décrite et non sur un financement ou un paiement indépendant. La piste documentaire évite une correction comptée deux fois.'],
['Base corrigée','Sous les hypothèses données, la TVA de l’avoir se calcule sur sa base HT.','Le taux de l’exercice est une donnée du cas, pas une affirmation sur toutes les opérations. Présentez séparément diminution HT et taxe correspondante. Le total TTC doit permettre un rapprochement avec la dette. Un montant TTC utilisé directement comme base HT conduirait à une erreur d’unité et de calcul.'],
['Dette','La correction de la dette et son paiement sont deux événements distincts.','Un avoir peut diminuer un montant dû sans mouvement immédiat de banque. Si la facture est déjà réglée, les modalités du remboursement ou de l’imputation demandent un examen distinct. Le dossier ne permet pas d’inventer un remboursement effectué. La chronologie est aussi importante que l’exactitude des montants.'],
['Contrôle','La somme HT et TVA doit retrouver le total TTC de la correction.','Un rapprochement numérique détecte une incohérence de montant, mais ne valide pas tout le régime de TVA. Vérifiez aussi références, sens de l’écriture et période. Les pièces doivent permettre de suivre le montant avant correction, l’avoir et le montant restant. Cette présentation conserve une trace vérifiable du calcul.']],
'Facture de 1 000 € HT avec un taux de 20 % fourni. Avant tout paiement, un avoir réduit de 100 € HT le prix de cette même opération. Pour cet exercice, l’avoir corrige la base et la taxe au même taux ; aucune autre opération n’intervient.',[
['Calculez l’avoir TTC.','TVA de l’avoir : 100 × 20 % = 20 €. Total de la diminution : 100 + 20 = 120 € TTC.'],
['Quel montant reste dû ?','Facture initiale : 1 200 € TTC. Après l’avoir de 120 €, il reste 1 080 € TTC.'],
['Un mouvement de banque est-il établi ?','Non. Le cas précise qu’aucun paiement n’a eu lieu ; la correction porte ici sur le montant dû.']],[S.vat,S.bofip]),
UE5:d('Dossier de synthèse : productivité et portée des comparaisons',
'Une variation de production peut provenir du volume de travail, de la productivité ou de leur combinaison. Le dossier apprend à définir la mesure et à conserver le périmètre. Un indicateur calculé correctement ne renseigne pas automatiquement sur la qualité du produit, sa répartition ou ses effets.',
'Définissez production et facteur utilisé. Calculez sur une base comparable, puis distinguez résultat descriptif et explication causale.',[
['Productivité horaire','La productivité horaire rapporte une production au volume d’heures correspondant.','Le numérateur et le dénominateur doivent porter sur le même champ. Un montant de ventes peut aussi dépendre des prix : il ne se substitue pas sans examen à un volume physique. Indiquez ce que mesure le ratio et son unité. Une mesure partielle ne représente pas toutes les dimensions de l’efficacité productive.'],
['Périmètre','Une comparaison exige des conventions et un champ compatibles.','Comparer deux ateliers demande de vérifier activité, période et qualité des produits. Un changement de méthode de mesure peut créer une variation apparente. Relevez les différences avant d’attribuer l’écart à une meilleure organisation. Le calcul doit rester traçable et la conclusion proportionnée aux informations du dossier.'],
['Variation','Un taux de variation utilise la valeur initiale comme base.','La différence absolue et le changement relatif ne sont pas la même grandeur. Une hausse de cinq unités n’a pas la même ampleur à partir de dix ou de cent. Présentez niveau initial, niveau final et variation. La base doit être indiquée pour permettre de contrôler l’interprétation du pourcentage.'],
['Causalité','Une amélioration observée n’établit pas seule sa cause.','Le matériel, la formation, l’organisation et la composition de l’activité peuvent évoluer simultanément. Un tableau décrit un résultat ; isoler un effet nécessite une méthode et davantage de données. Vous pouvez proposer une hypothèse explicative en la distinguant du constat. Ne transformez pas une corrélation en démonstration automatique.']],
'Un atelier produit 1 200 unités en 600 heures, puis 1 500 unités en 600 heures. Le produit et la méthode de comptage sont supposés comparables. Aucune information ne permet d’isoler une cause de l’évolution.',[
['Calculez les deux productivités horaires.','Première période : 1 200 / 600 = 2 unités par heure. Deuxième : 1 500 / 600 = 2,5 unités par heure.'],
['Calculez le taux d’évolution.','(2,5 − 2) / 2 = 25 %. La base est la productivité initiale de 2 unités par heure.'],
['Peut-on attribuer cette hausse à une formation ?','Non. Les données établissent la variation mesurée, sans isoler l’effet d’une formation.']],[S.economy]),
UE6:d('Dossier de synthèse : croissance et tensions de trésorerie',
'Le bénéfice et la trésorerie ne suivent pas nécessairement le même rythme. Une entreprise peut vendre davantage tout en immobilisant des fonds dans son exploitation. Le dossier combine des hypothèses simples pour relier encaissements, créances, stocks et dette fournisseur.',
'Séparez résultat et flux. Décomposez le BFR selon la convention donnée, puis calculez sa variation et les facteurs à examiner.',[
['Créances','Une vente non encaissée ne fournit pas immédiatement toute sa trésorerie.','Elle peut contribuer au résultat tout en laissant une créance. Pour analyser le financement de l’activité, repérez les échéances et les paiements effectifs. Ne concluez pas à une absence de difficulté à partir du seul chiffre d’affaires. Le besoin de financement dépend notamment de la durée des décalages.'],
['Besoin d’exploitation','Dans le modèle fourni, le BFR égale stocks plus créances moins dettes fournisseurs.','Chaque composante doit être mesurée sur le même périmètre. Une augmentation des stocks et des créances peut consommer des ressources, tandis que des délais fournisseurs peuvent en financer une partie. La formule donnée est une convention de ce dossier simplifié ; elle ne remplace pas le diagnostic complet de tous les postes.'],
['Variation du besoin','Une hausse du BFR traduit, sous ce modèle, davantage de fonds immobilisés dans l’exploitation.','Distinguez le niveau du besoin et son évolution. Un BFR élevé mais stable et une forte hausse ponctuelle ne posent pas exactement la même question de financement. Le tableau de passage permet de relier chaque variation au facteur concerné. La conclusion ne doit pas confondre consommation de ressources et charge comptable.'],
['Décision','Une action sur les délais exige d’examiner ses contraintes commerciales et opérationnelles.','Réduire un délai client peut aider la trésorerie sans être réalisable partout. Réduire le stock peut aussi créer des ruptures. La recommandation doit expliquer le bénéfice attendu, le risque associé et l’indicateur de suivi. Une mesure ponctuelle ne garantit pas que le besoin futur sera couvert.']],
'Modèle simplifié : stocks 20 000 €, créances clients 30 000 €, dettes fournisseurs 18 000 €. Ensuite, stocks 25 000 €, créances 40 000 €, dettes fournisseurs 20 000 €. Les autres postes sont exclus explicitement de ce calcul.',[
['Calculez le BFR initial et final.','Initial : 20 000 + 30 000 − 18 000 = 32 000 €. Final : 25 000 + 40 000 − 20 000 = 45 000 €.'],
['Quelle est la variation ?','Le besoin augmente de 45 000 − 32 000 = 13 000 € dans le modèle fourni.'],
['Proposez une analyse avant une action.','Étudier les délais clients et les stocks, leurs causes et leurs contraintes. La hausse des dettes fournisseurs ne compense ici qu’une partie de la hausse des emplois.']],[S.finance]),
UE7:d('Dossier de synthèse : arbitrer entre parties prenantes',
'Une décision d’organisation peut satisfaire un objectif et créer une difficulté pour un autre acteur. Le dossier travaille les critères de comparaison, les effets attendus et le suivi. Un arbitrage doit rendre ses raisons visibles plutôt que prétendre que tous les intérêts coïncident.',
'Identifiez acteurs, attentes et contraintes. Comparez les options selon des critères communs et définissez les contrôles après décision.',[
['Attentes','Les parties prenantes peuvent avoir des attentes différentes.','Client, salarié, direction et fournisseur ne jugent pas toujours la même performance. La qualité de service, la charge de travail, le coût et la prévisibilité peuvent entrer en tension. Relevez les attentes présentes dans le dossier, sans inventer un accord général. Un objectif doit être situé dans ce contexte.'],
['Critères','Les options doivent être comparées sur une même grille.','Un prix faible et un délai court ne sont pas directement substituables. Définissez les dimensions et les contraintes avant de choisir. Une grille ne supprime pas le jugement, mais rend l’arbitrage explicite. Les critères oubliés doivent être recherchés lorsqu’une option semble meilleure uniquement grâce à une information incomplète.'],
['Effets secondaires','Une mesure peut produire des comportements non recherchés.','Récompenser la vitesse peut conduire à négliger une vérification si aucun contrôle de qualité n’accompagne la mesure. Il ne faut pas présenter cet effet comme certain, mais comme un risque à examiner. Le dossier doit relier les incitations aux possibilités réelles d’action et aux contraintes du travail.'],
['Suivi','Une décision doit être accompagnée d’un indicateur et d’un point de contrôle.','Précisez responsable, fréquence et signe d’alerte. Le nombre de tâches terminées ne suffit pas toujours pour observer qualité et satisfaction. Le suivi doit permettre de réexaminer l’action si ses effets diffèrent des attentes. Un indicateur utile soutient une décision, au lieu de seulement remplir un tableau.']],
'Une équipe envisage de traiter plus vite les demandes clients. Une option réduit une vérification ; une autre conserve le contrôle et change la répartition du travail. Les clients demandent rapidité et fiabilité ; l’équipe signale une charge élevée.',[
['Quels intérêts mettre en relation ?','Rapidité et fiabilité pour les clients, charge de travail pour l’équipe, coût et qualité pour l’organisation.'],
['Quelle comparaison construire ?','Évaluer délai, erreurs, charge, moyens nécessaires et contraintes sur les deux options, plutôt que retenir le seul délai annoncé.'],
['Quel suivi proposer ?','Délai de traitement et taux d’erreur, avec un responsable, une fréquence et une revue de la charge de travail.']],[S.economy]),
UE8:d('Dossier de synthèse : tester une requête avant son utilisation',
'Une requête doit être vérifiée selon le besoin qu’elle représente. Ce dossier travaille la granularité des lignes, les doublons, les absences de correspondance et les agrégations. Une exécution sans message d’erreur ne prouve pas que le résultat répond à la question.',
'Écrivez le résultat attendu sur un jeu limité. Précisez la granularité, testez les liens, puis contrôlez le résultat agrégé.',[
['Granularité','La signification d’une ligne doit être définie avant le comptage.','Une table de clients et une table de commandes ne représentent pas le même objet. Après une jointure, un client peut apparaître plusieurs fois. Le nombre de lignes obtenu peut donc mesurer des commandes plutôt que des clients. Commencez par exprimer en mots l’unité que votre résultat doit compter.'],
['Absence de lien','Un client sans commande doit être traité selon le besoin de la requête.','Le résultat attendu peut l’inclure ou l’exclure. Une jointure doit être choisie en conséquence, sans supposer que toutes les clés possèdent une correspondance. Testez ce cas explicitement. Les lignes manquantes peuvent être une conséquence logique du traitement ou une anomalie du jeu de données ; il faut distinguer les deux.'],
['Doublons','Une relation à plusieurs lignes peut multiplier les montants après jointure.','Un total calculé à partir d’un montant répété peut être surévalué. Vérifiez la cardinalité et le niveau où le montant est défini. La suppression automatique de doublons n’est pas une solution universelle : elle peut effacer des opérations distinctes. Le contrôle doit respecter le sens de chaque enregistrement.'],
['Test attendu','Un jeu de test doit couvrir les situations qui pourraient modifier le résultat.','Utilisez un client avec deux commandes, un avec une commande et un sans commande. Écrivez le résultat attendu avant la requête. Un rapprochement permet de repérer un défaut de logique. Il ne valide pas toutes les données futures, mais rend le traitement vérifiable et aide à concevoir les contrôles suivants.']],
'Trois clients A, B et C. A possède deux commandes ; B en possède une ; C n’en possède aucune. On cherche le nombre de clients ayant au moins une commande, sans compter deux fois le même client.',[
['Quel est le résultat attendu ?','Deux clients : A et B. Les trois commandes ne représentent pas trois clients distincts.'],
['Que risque un simple comptage des lignes jointes ?','Compter trois commandes au lieu de deux clients si la jointure produit une ligne par commande.'],
['Quel test complémentaire est utile ?','Vérifier le traitement de C et la règle de comptage distinct, puis ajouter un cas de valeur manquante selon le besoin.']],[S.privacy,S.cyber]),
UE9:d('Dossier de synthèse : passer d’une pièce aux états financiers',
'Ce dossier associe qualification, enregistrement, règlement et contrôle. Il illustre pourquoi une balance équilibrée peut encore contenir une erreur. Les hypothèses simplifiées permettent de suivre une opération sans mélanger charge, dette et mouvement de banque.',
'Identifiez l’opération et sa date. Distinguez facture et paiement, puis vérifiez comptes, période, montants et pièce justificative.',[
['Facture','Une facture et son règlement doivent être distingués dans la chronologie.','La facture peut constater une charge et une dette avant tout paiement. Le paiement peut ensuite solder la dette, sans créer une seconde charge pour la même prestation. Les montants et les comptes doivent être rapprochés de la pièce initiale. Le raisonnement conserve la distinction entre résultat et trésorerie.'],
['Partie double','L’égalité débit et crédit ne garantit pas toute l’exactitude d’une écriture.','Une écriture peut être équilibrée avec une mauvaise période ou un mauvais compte. Le contrôle arithmétique est nécessaire mais doit être complété par la qualification. Rapprochez l’écriture de la nature de l’opération, de sa réalisation et du document. Une balance ne remplace pas cette piste de vérification.'],
['Règlement','Le règlement d’une dette fournisseur ne devient pas automatiquement une nouvelle charge.','Identifiez la dette que le mouvement de banque dénoue. Une mauvaise lecture peut doubler la charge et laisser un solde fournisseur incorrect. Le contrôle doit faire le lien entre facture, dette et paiement. Si le montant payé diffère, recherchez l’avoir ou la condition de règlement au lieu d’inventer une explication.'],
['Contrôle de clôture','Les comptes et la période doivent être vérifiés à partir des faits.','La date de paiement ne définit pas automatiquement la période de la prestation. Le dossier doit préciser quand le service a été réalisé et s’il faut une régularisation. Les hypothèses données permettent ici un traitement simplifié. Dans une situation plus complète, il faut également examiner taxes, justificatifs et règles applicables.']],
'Service réalisé et facturé 600 € dans l’exercice, sans TVA par hypothèse pédagogique. La facture constate une charge et une dette. Le paiement intervient ensuite et solde entièrement cette dette. Aucune autre opération ni régularisation n’est nécessaire dans ce cas.',[
['Quel effet a la facture ?','Elle constate ici une charge de 600 € et une dette de 600 €, sans paiement immédiat.'],
['Quel effet a le règlement ?','Il diminue la banque et solde la dette de 600 €. Il ne crée pas une seconde charge de cette prestation.'],
['Quel contrôle détecterait une double charge ?','Rapprocher facture, écriture initiale et règlement, puis vérifier le solde fournisseur et le compte de charge.']],[S.pcg]),
UE10:d('Dossier de synthèse : justifier une estimation comptable',
'Une estimation produit un montant à partir de données et d’hypothèses. Le dossier travaille leur traçabilité, la différence entre changement d’information et erreur, et les limites d’un résultat. Une précision numérique ne constitue pas à elle seule une preuve de qualité.',
'Identifiez ce qui est estimé, les données et hypothèses. Reconstituez la chronologie puis examinez le traitement dans le référentiel retenu.',[
['Données','Une estimation doit être reliée à des informations identifiables.','Distinguez une donnée observée, une prévision et une convention du modèle. La provenance et la date de l’information comptent pour apprécier sa pertinence. Un chiffre repris d’un exercice antérieur ne devient pas automatiquement une hypothèse adaptée au nouvel exercice. Documentez les éléments qui soutiennent le montant proposé.'],
['Hypothèse','Une hypothèse doit être explicite pour permettre une discussion de l’estimation.','Une durée, un volume ou une probabilité peut modifier fortement le résultat. La cohérence entre les hypothèses doit être examinée. Le fait qu’un calcul utilise toutes ses cellules ne prouve pas que ses paramètres conviennent. Une hypothèse inconnue ne doit pas être remplacée silencieusement par une valeur choisie pour obtenir le résultat souhaité.'],
['Information nouvelle','Une information nouvelle ne prouve pas automatiquement une erreur passée.','Comparez les informations disponibles à chaque date. L’estimation initiale peut avoir été raisonnable sous les données d’alors. Une donnée déjà disponible mais ignorée soulève une question différente. La qualification et le traitement doivent être examinés dans le référentiel retenu, sans supposer qu’un changement et une erreur produisent toujours les mêmes effets.'],
['Sensibilité','La sensibilité montre comment le résultat dépend d’une hypothèse.','Changer un paramètre permet de rendre visible l’incertitude du modèle. Cela ne produit pas une nouvelle preuve ni une prédiction certaine. Présentez les valeurs testées et le périmètre. La recommandation doit expliquer ce qui reste robuste et ce qui demande des informations complémentaires avant de retenir une estimation.']],
'Un matériel amortissable présente une valeur de référence de 12 000 € répartie sur quatre ans dans un modèle linéaire sans valeur résiduelle. Le modèle calcule 3 000 € par an. Une nouvelle information suggère d’examiner la durée, sans indiquer le traitement comptable définitif.',[
['Que justifie le montant de 3 000 € dans ce modèle ?','12 000 / 4 = 3 000 € par année complète, sous les hypothèses explicites de ce calcul.'],
['La nouvelle information prouve-t-elle une erreur initiale ?','Non. Il faut comparer les informations disponibles et qualifier la situation dans le référentiel retenu.'],
['Que documenter avant de conclure ?','Nature et date de l’information, justification de la durée et du modèle, référentiel et traitement à examiner.']],[S.pcg]),
};
Object.assign(SYNTHESIS_DATA,{
UE11:d('Dossier de synthèse : mesurer la qualité sans perdre le sens',
'Un indicateur de qualité doit être relié à un processus, à un périmètre et à une décision. Le dossier associe fréquence des incidents et coût de traitement. Les calculs n’expliquent pas seuls les causes ni la satisfaction des clients.',
'Définissez unité et population. Rapprochez fréquence, coût et causes documentées, puis proposez une action et un suivi.',[
['Population','Un taux exige un numérateur et un dénominateur compatibles.','Comptez des incidents, des produits ou des clients selon la question. Plusieurs incidents sur un même produit peuvent modifier le sens du ratio. Un pourcentage n’est interprétable qu’avec sa population et sa période. Une variation du volume total peut aussi expliquer un changement du nombre d’incidents sans changement du taux.'],
['Coût de traitement','Un coût moyen donné permet un calcul sous ses hypothèses.','Précisez ce qu’il comprend et ce qu’il exclut. Une estimation des frais de reprise ne mesure pas automatiquement toute la perte commerciale. Il ne faut pas ajouter une perte de clientèle ou une pénalité absente du cas. Distinguez coût calculé, coût documenté et conséquence possible à examiner.'],
['Diagnostic','Un taux d’incident ne démontre pas automatiquement la cause.','Distinguez défaut de matière, réglage, contrôle ou organisation lorsque les informations le permettent. Les catégories doivent être comparables et les faits documentés. Un indicateur peut révéler un signal sans attribuer une responsabilité. Le diagnostic doit précéder l’action pour éviter de traiter seulement le symptôme.'],
['Suivi','Une action corrective doit être suivie sur une période et un périmètre définis.','La baisse du nombre d’incidents peut venir d’une baisse du volume traité. Comparez les taux et les effets sur le délai et le coût. Un contrôle complémentaire peut aussi consommer des ressources. L’évaluation doit observer le bénéfice et les contraintes plutôt que seulement l’installation de la mesure.']],
'Sur 1 000 produits contrôlés, 20 nécessitent une reprise. Le coût de reprise est supposé constant à 30 € par produit, sans autre coût. Les causes ne sont pas documentées.',[
['Calculez le taux de reprise.','20 / 1 000 = 2 %. Le dénominateur correspond aux produits contrôlés.'],
['Calculez le coût de reprise sous ces hypothèses.','20 × 30 = 600 €, sans ajouter les coûts exclus du modèle.'],
['Quelle étape précède une action ciblée ?','Documenter et classer les causes, puis choisir une action avec un suivi du taux, du coût et du délai.']],[S.pcg]),
UE12:d('Business English : distinguer constat, prévision et engagement',
'A professional message may report a result, forecast a change or request an action. Ce dossier travaille ces distinctions pour éviter de transformer une possibilité en promesse. Les exemples sont des créations pédagogiques et les activités sont réalisées par écrit.',
'Identify the purpose and evidence. Choose wording that matches certainty, then state the action or limit clearly.',[
['Observed result','Sales increased by 8% last year reports an observed change.','La phrase présente une évolution passée. Elle n’annonce pas automatiquement le même résultat l’année suivante. Conservez la période et la base de comparaison. Pour un texte chiffré, vérifiez aussi devise, unité et champ. Une traduction correcte doit conserver le statut du fait et ne pas ajouter sa cause.'],
['Forecast','Sales may increase next year expresses a possibility rather than a guaranteed result.','May indique ici une possibilité. A forecast depends on assumptions : une prévision doit être reliée aux hypothèses disponibles. Le vocabulaire de certitude ne doit pas être renforcé lors de la reformulation. L’analyse du document distingue le scénario envisagé et ce qui a effectivement été observé.'],
['Request','Could you confirm the delivery date? asks for information.','La question demande une confirmation ; elle ne démontre pas qu’un engagement a déjà été obtenu. Une demande professionnelle précise objet et référence. Le destinataire doit comprendre ce qui est attendu sans deviner le dossier. Relisez la phrase d’action et les documents mentionnés avant d’envoyer un message réel.'],
['Qualified recommendation','We recommend reviewing the forecast because demand remains uncertain gives a reason.','La recommandation est soutenue par une incertitude identifiée. Elle ne doit pas introduire une donnée absente du document. Une formulation simple peut exprimer position, justification et limite. Le lecteur doit pouvoir distinguer information source et avis de l’auteur, même lorsque les deux figurent dans le même paragraphe.']],
'A report states: Sales increased by 8% last year. Demand remains uncertain. Sales may increase next year. A colleague asks for a delivery date that has not yet been confirmed.',[
['Which statement is an observed result?','Sales increased by 8% last year. It reports the past change given in the document.'],
['Which phrase should not become a guarantee?','Sales may increase next year. The wording expresses a possibility under uncertainty.'],
['Write a clear request about delivery.','Could you please confirm the delivery date? This requests information without claiming that confirmation already exists.']],[SOURCES_EN()]),
UE13:d('Dossier de synthèse : justifier une amélioration dans un rapport',
'Un rapport peut constater une amélioration sans pouvoir en attribuer toute la cause à votre action. Le dossier relie données, contribution personnelle et limites. Cette distinction rend une analyse professionnelle plus solide qu’une affirmation de réussite non documentée.',
'Définissez indicateur et période. Décrivez votre contribution, comparez les données puis exposez les limites de l’interprétation.',[
['Indicateur','La mesure doit préciser population, période et convention.','Un nombre d’erreurs et un taux d’erreur ne se comparent pas directement. Le volume d’activité peut changer. Indiquez ce qui est compté et la source du chiffre. Le lecteur doit pouvoir comprendre le calcul sans reconstruire les hypothèses. Une annexe utile rend cette vérification possible.'],
['Contribution','Votre contribution doit être distinguée de celle de l’équipe.','Présentez les tâches réalisées et les choix auxquels vous avez participé. Un résultat global ne démontre pas que vous en êtes l’unique cause. Une analyse peut rester personnelle tout en reconnaissant les autres acteurs. Cette précision permet aussi de répondre aux questions sur le périmètre exact de la mission.'],
['Causalité','Une comparaison avant et après n’isole pas automatiquement un effet causal.','Le volume, les outils et l’organisation peuvent changer simultanément. Le rapport peut formuler une explication plausible en la distinguant du résultat observé. Une limite documentée renforce la précision de l’analyse. N’ajoutez pas un groupe de comparaison ou une mesure qui n’a pas été réalisé.'],
['Référence','Une affirmation chiffrée doit pouvoir être rattachée à une source autorisée.','Expliquez les extractions et les traitements nécessaires au calcul. Les pièces confidentielles doivent être utilisées avec les précautions appropriées. Une reformulation d’une source externe conserve la nécessité de la référencer. Votre analyse personnelle doit être visible dans le raisonnement, pas dans la disparition des références.']],
'Avant une mission, 12 dossiers sur 300 comportent une erreur. Après, 6 dossiers sur 300 en comportent une. Vous avez créé une grille de contrôle ; l’équipe a aussi reçu une formation. Les deux périodes sont comparables pour ce calcul.',[
['Calculez les deux taux.','12 / 300 = 4 %. Puis 6 / 300 = 2 %. Le taux baisse de 2 points de pourcentage, soit une réduction relative de 50 %.'],
['Pouvez-vous attribuer toute la baisse à votre grille ?','Non. La formation constitue aussi un changement. La comparaison ne permet pas d’isoler la contribution de chaque action.'],
['Comment rédiger la conclusion ?','Décrire la baisse observée, votre contribution précise et la limite causale ; documenter les données et les calculs avec des pièces autorisées.']],[PROGRAM_COMM()]),
DSCG1:d('Dossier de synthèse : organiser une revue documentaire d’acquisition',
'Une revue documentaire prépare une décision sans transformer une liste de pièces en validation générale. Le dossier apprend à relier objectif, risque, document et contrôle. Les conséquences juridiques ou fiscales doivent ensuite être examinées dans leur cadre propre.',
'Précisez ce qui est acquis. Pour chaque risque, associez pièce, contrôle, conclusion possible et information manquante.',[
['Périmètre','La revue doit préciser l’opération et les éléments concernés.','Titres, actifs et contrats ne décrivent pas le même périmètre. Une pièce pertinente pour l’un ne répond pas nécessairement au contrôle de l’autre. Identifiez les entités et la chronologie. L’objet de l’acquisition commande les questions, sans que l’accord sur le prix suffise à résoudre toutes les incertitudes.'],
['Lien documentaire','La pièce doit être reliée au risque que l’on cherche à apprécier.','Demander tous les documents sans objectif rend la revue difficile à exploiter. Un contrat éclaire des engagements ; un tableau financier peut renseigner des montants. Il faut aussi apprécier version, auteur et complétude. Le fait qu’un document soit remis ne prouve pas que son contenu a été validé.'],
['Condition manquante','Une pièce absente doit être traduite en contrôle restant.','Une réserve utile indique la conclusion qui ne peut pas encore être tirée. Elle peut aussi préciser une démarche ou une priorité avant engagement. N’inventez pas la clause manquante pour achever le raisonnement. La revue doit distinguer information obtenue, information contradictoire et élément non fourni.'],
['Recommandation','Une recommandation opérationnelle peut organiser les vérifications avant décision.','Précisez responsable, échéance et dépendance entre les contrôles. Les analyses juridique, fiscale et sociale doivent garder leurs fondements propres. La revue peut soutenir un arbitrage, sans constituer une garantie d’absence de risque. La conclusion doit présenter les limites du dossier et les conditions de l’option envisagée.']],
'Une acquisition de titres est envisagée. Le contrat de financement est fourni, mais une annexe sur les garanties manque. La liste du personnel et les comptes sont disponibles ; aucune validation fiscale n’est donnée.',[
['Quel périmètre identifier ?','L’opération porte ici sur des titres. Les engagements et les risques de la société cible demandent leurs contrôles propres.'],
['Que signifie l’absence de l’annexe ?','Le contenu des garanties ne peut pas être tenu pour connu. Il faut obtenir la version pertinente et examiner ses effets.'],
['Quelle conclusion opérationnelle proposer ?','Organiser les contrôles prioritaires et leurs responsables ; distinguer les éléments disponibles des validations encore nécessaires avant engagement.']],[S.civil,S.company,S.bofip]),
DSCG2:d('Dossier de synthèse : raisonner avec des scénarios financiers',
'Un scénario rend une hypothèse visible ; il ne prédit pas nécessairement l’avenir. Le dossier combine résultats et probabilités fournies, puis distingue moyenne, dispersion et liquidité. Les chiffres sont des hypothèses pédagogiques, sans recommandation d’investissement.',
'Vérifiez les scénarios et leur probabilité. Calculez le résultat pondéré, puis présentez risque, limites et horizon.',[
['Probabilité','Les probabilités du modèle doivent former une distribution cohérente.','Dans les scénarios exclusifs et exhaustifs du cas, leur somme doit être égale à 100 %. Ce contrôle ne démontre pas que les probabilités décrivent correctement le futur. Présentez leur provenance ou leur caractère hypothétique. Un scénario oublié peut modifier l’interprétation de toute la moyenne calculée.'],
['Résultat attendu','Le résultat attendu est une moyenne pondérée des scénarios du modèle.','Multipliez chaque résultat par sa probabilité, puis additionnez. La moyenne peut ne correspondre à aucun scénario effectivement réalisé. Elle ne constitue pas une promesse de gain. L’horizon et les unités doivent être conservés pour permettre une comparaison avec un autre modèle.'],
['Dispersion','Une même moyenne peut masquer des résultats possibles très différents.','La dispersion et les pertes possibles doivent être examinées séparément du résultat moyen. Deux opérations peuvent partager une espérance sans présenter le même risque. Le dossier simplifié ne permet pas de mesurer toutes les expositions. Signalez les scénarios défavorables et les informations nécessaires à une analyse plus complète.'],
['Liquidité','Un rendement attendu ne démontre pas la disponibilité des fonds à l’échéance voulue.','Le calendrier des besoins et les conditions de sortie comptent pour une décision. Un résultat intéressant peut rester incompatible avec un besoin de trésorerie proche. Distinguez possibilité de revendre, prix de sortie et délai. Le modèle de scénarios ne doit pas masquer ces contraintes.']],
'Un modèle hypothétique donne deux scénarios exclusifs : résultat de 10 € avec probabilité 60 %, perte de 5 € avec probabilité 40 %. Aucun autre scénario n’est prévu dans ce modèle ; il ne décrit pas un placement proposé à l’élève.',[
['Vérifiez la somme des probabilités.','60 % + 40 % = 100 %, ce qui respecte la distribution supposée dans ce modèle.'],
['Calculez le résultat attendu.','0,60 × 10 + 0,40 × (−5) = 4 €. Ce montant est une moyenne du modèle, sans garantie de réalisation.'],
['Pourquoi la moyenne ne suffit-elle pas ?','Elle ne décrit pas seule la dispersion, les pertes possibles ni la liquidité. Le scénario de perte et les limites des hypothèses restent à examiner.']],[S.finance,S.diversification]),
DSCG3:d('Dossier de synthèse : relier indicateurs et comportements',
'Un indicateur de performance peut modifier les décisions de ceux qui le suivent. Le dossier examine une incitation locale, ses conséquences possibles et les contrôles complémentaires. Une mesure ne doit pas être confondue avec l’objectif global.',
'Définissez objectif, périmètre et pouvoir d’action. Analysez les comportements possibles, puis proposez des mesures complémentaires.',[
['Objectif global','Un résultat local doit être rapproché de l’objectif de l’organisation.','Une baisse de coût peut détériorer délai, qualité ou coopération. Un responsable peut atteindre sa cible tout en déplaçant une difficulté vers une autre unité. L’analyse doit identifier les interdépendances. Une mesure isolée ne permet pas de conclure à une amélioration globale sans examiner ses autres effets.'],
['Pouvoir d’action','L’attribution d’un résultat doit tenir compte de ce que le responsable peut influencer.','Un écart peut dépendre de décisions extérieures à son périmètre. La mesure reste informative, mais la responsabilité doit être analysée séparément. Définissez variables contrôlables et dépendances. Cela évite une attribution automatique qui rendrait le dispositif de pilotage difficile à comprendre ou contre-productif.'],
['Incitation','Une récompense peut encourager des comportements qui ne servent pas tous les objectifs.','Une cible de rapidité peut rendre la vérification moins attractive si elle consomme du temps non valorisé. L’effet n’est pas certain, mais mérite un contrôle. Examinez la manière dont les acteurs peuvent atteindre la cible et les effets secondaires possibles. Une règle de rémunération ne remplace pas une analyse du processus.'],
['Mesures complémentaires','Les indicateurs doivent permettre de vérifier les effets secondaires pertinents.','Délai, erreur, réclamation et charge de travail peuvent éclairer différentes dimensions. Ajouter des mesures ne suffit pas : chacune doit soutenir une décision et disposer de données fiables. Précisez fréquence et responsable. Le suivi permet de réviser l’incitation lorsque les comportements observés diffèrent de ceux recherchés.']],
'Une unité est récompensée uniquement selon le nombre de dossiers traités. Le responsable peut agir sur la répartition du travail, mais pas sur le nombre de demandes reçues. Des vérifications pourraient être raccourcies pour augmenter le volume traité.',[
['Quel objectif local ne doit pas être confondu avec la performance globale ?','Le nombre de dossiers traités ne mesure pas seul qualité, délai, coopération et satisfaction.'],
['Quelle limite de responsabilité identifier ?','Le responsable ne contrôle pas le volume des demandes reçues, alors qu’il peut agir sur leur organisation.'],
['Quels contrôles compléter ?','Suivre erreurs, réclamations, délai et charge sur le même périmètre, avec une revue des effets de l’incitation.']],[S.economy]),
DSCG4:d('Dossier de synthèse : tester les assertions sur un stock',
'Le stock peut soulever des questions d’existence, d’exhaustivité, d’appartenance et d’évaluation. Chaque assertion conduit à une lecture et à des travaux différents. Le dossier apprend à relier le risque et la procédure, sans prétendre produire une opinion d’audit complète.',
'Nommez l’assertion. Choisissez le sens du contrôle et les pièces utiles, puis précisez ce que la preuve obtenue ne démontre pas.',[
['Existence','Partir d’une ligne enregistrée pour rechercher le bien vise son existence.','La procédure vérifie un objet qui figure déjà dans les données comptables. Le fait de trouver ce bien ne démontre pas que tous les autres biens sont enregistrés. Le sens du test doit être explicite. La qualité de la preuve dépend aussi des conditions d’observation et du périmètre effectivement examiné.'],
['Exhaustivité','Partir d’un bien observé pour rechercher son enregistrement vise l’exhaustivité.','Cette direction permet de rechercher des éléments qui pourraient manquer aux données. Elle répond à une question différente du test d’existence. Un relevé physique ne prouve pas à lui seul l’appartenance ou la valeur. Les travaux doivent conserver la distinction entre les assertions plutôt que considérer un contrôle comme suffisant pour toutes.'],
['Appartenance','La présence physique ne démontre pas automatiquement les droits sur le bien.','Des biens détenus peuvent appartenir à un tiers. Les contrats et documents de réception ou de dépôt doivent être examinés selon la situation. Ne transformez pas une observation en preuve universelle de propriété. La conclusion doit indiquer les pièces obtenues et les informations encore nécessaires.'],
['Évaluation','La quantité observée et la valeur comptable demandent des contrôles distincts.','Des biens peuvent être présents mais endommagés ou obsolètes. Le coût et les éventuelles pertes de valeur doivent être examinés dans le référentiel retenu. Le dossier ne permet pas d’inventer un montant de dépréciation. La preuve doit être reliée au risque et aux données qui soutiennent l’évaluation.']],
'Une liste comptable comporte une ligne de 100 pièces. Le contrôleur observe ces pièces, puis repère un autre lot non retrouvé sur la liste. Certaines pièces appartiennent à un tiers selon un contrat de dépôt ; aucune valeur corrigée n’est fournie.',[
['Quelle assertion vise la recherche des 100 pièces ?','L’existence de la ligne enregistrée, sans valider automatiquement toutes les autres assertions.'],
['Quelle question pose le lot absent de la liste ?','L’exhaustivité des enregistrements, à examiner avec le périmètre et les documents pertinents.'],
['Pourquoi la présence ne suffit-elle pas ?','Elle n’établit pas seule appartenance et évaluation. Le dépôt et l’état des biens exigent des contrôles distincts.']],[['Normes internationales d’audit, IAASB','https://www.iaasb.org/standards-pronouncements'],S.pcg]),
DSCG5:d('Dossier de synthèse : tester un plan de reprise',
'Un plan de reprise doit être relié aux besoins métiers et vérifié par des exercices. Le dossier distingue durée d’interruption et perte de données admissible. Une sauvegarde disponible ne démontre pas à elle seule que le service peut redémarrer dans les conditions attendues.',
'Définissez service critique, durée et perte admissibles. Comparez le test aux objectifs, puis documentez les écarts et les actions.',[
['Objectif de temps','Le RTO décrit un objectif de temps de reprise du service.','Il doit être relié aux besoins et aux dépendances de l’activité. Un objectif annoncé n’est pas la durée effectivement obtenue lors d’un incident ou d’un exercice. Le test doit préciser début, fin et périmètre. Une reprise technique partielle peut ne pas rétablir toutes les fonctions utiles au métier.'],
['Objectif de données','Le RPO décrit le point de reprise et la perte de données admissible.','La quantité d’activité qui pourrait manquer doit être appréciée selon la fenêtre retenue. Un objectif de deux heures n’est pas un délai de restauration de deux heures. La fréquence de sauvegarde compte, mais doit être reliée aux autres conditions du dispositif. Les objectifs de temps et de données restent distincts.'],
['Exercice','Un test doit vérifier la restauration et les dépendances du service.','La présence d’un fichier de sauvegarde ne prouve pas sa lecture ni la remise en service. Examinez accès, intégrité, applications et conditions d’exploitation. Le résultat doit être documenté, avec les limites du périmètre testé. Un essai réussi sur un composant ne valide pas automatiquement toute la reprise.'],
['Écart','Un écart observé doit être relié à une action et à un nouveau contrôle.','Décrivez objectif, résultat et cause documentée. Une mesure corrective doit avoir un responsable et un calendrier. Le plan doit aussi rester adapté lorsque applications ou besoins métiers changent. Les conditions du test et l’évolution du système doivent être conservées pour apprécier la portée de la conclusion.']],
'Objectifs hypothétiques : reprendre en quatre heures et ne perdre au maximum que deux heures de données. Le test reprend le service en six heures avec une perte d’une heure. Le périmètre testé est supposé correspondre au service prévu.',[
['L’objectif de temps est-il respecté ?','Non. Six heures dépassent l’objectif de quatre heures de deux heures.'],
['L’objectif de perte de données est-il respecté ?','Oui dans ce test : une heure de perte reste sous le maximum donné de deux heures.'],
['Quelle action organiser ?','Documenter les causes du retard de reprise, attribuer les actions et refaire un test sur le périmètre défini.']],[['Reprise d’activité, ANSSI','https://monservicesecurise.cyber.gouv.fr/referentiel-mesures'],S.cyber]),
DSCG6:d('Business English : discuss an ethical dilemma in writing',
'A business decision can involve a conflict between personal interests and professional responsibilities. This original exercise develops a written argument in English. It does not assess pronunciation or provide a legal conclusion about the scenario.',
'Name the issue, distinguish facts and assumptions, compare options and justify a qualified recommendation.',[
['Conflict of interest','A personal benefit may affect the independence of a professional decision.','Le risque doit être décrit à partir des faits, sans affirmer automatiquement une infraction juridique. Name the decision and the benefit, then explain the possible influence. A personal link does not establish every consequence by itself. The analysis should identify the concern and the information required to assess it.'],
['Evidence','A reasoned argument separates evidence from suspicion.','Distinguish what the case states and what you infer. A written comparison of bids can document criteria; it does not prove that every possible influence has disappeared. The explanation should identify both useful evidence and its limits. Avoid inventing facts to make the recommendation easier to defend.'],
['Alternatives','Options should be compared using consistent criteria.','Cost, quality, service and independence may all matter. The cheapest option is not automatically the best on every dimension. Explain the criteria and the trade-off. If a relevant criterion is missing, state what would need to be checked. A clear comparison is more useful than an unsupported preference.'],
['Recommendation','A qualified recommendation states an action, a reason and a condition.','You may recommend an independent review because the decision involves a personal benefit. This is an analytical proposal, not an assertion that a legal obligation has been established. The written response should answer the question directly and address a plausible objection. No microphone or voice analysis is involved in this exercise.']],
'A purchasing manager receives a personal gift from one bidder. The bids differ in price and service quality. Company policy is not provided. The manager is asked to recommend a supplier.',[
['What issue should be identified?','A possible conflict between the personal benefit and the independence of the supplier decision. The case does not establish a legal offence.'],
['What evidence and information are useful?','A documented comparison of bids and the relevant company policy, while distinguishing known facts from assumptions.'],
['Give a qualified recommendation.','I would recommend an independent review of the bids because the gift may affect confidence in the decision. The company policy should also be checked.']],[PROGRAM_COMM()]),
DSCG7:d('Dossier de synthèse : trianguler des observations de terrain',
'Plusieurs sources peuvent enrichir une analyse sans rendre toute conclusion certaine. Le dossier travaille comparaison, contradiction et biais de confirmation. La triangulation doit rendre le raisonnement plus traçable, sans compter chaque source comme une preuve équivalente.',
'Formulez la question. Comparez les sources, examinez les contradictions et distinguez observation, interprétation et portée.',[
['Triangulation','La triangulation confronte plusieurs sources ou méthodes autour d’une question.','Entretiens, documents et observations peuvent éclairer des dimensions différentes. Leur convergence constitue une information utile, sans certifier toutes les causes possibles. La comparaison doit préciser ce que chaque source apporte. Le nombre de sources ne remplace pas l’examen de leur qualité et de leur indépendance.'],
['Contradiction','Une contradiction doit être analysée plutôt qu’effacée du résultat.','Deux personnes peuvent décrire des périodes ou des périmètres différents. Un document peut utiliser une convention qui n’est pas celle de l’entretien. Recherchez l’origine de l’écart et conservez sa trace. La contradiction peut révéler une limite du terrain ou une question à approfondir, au lieu d’être une erreur à masquer.'],
['Confirmation','Le biais de confirmation conduit à privilégier les éléments favorables à une idée.','Le protocole doit permettre de rechercher aussi des éléments qui pourraient la remettre en cause. Une hypothèse de départ ne doit pas devenir une conclusion avant l’enquête. Documentez les critères de sélection et les analyses alternatives. Ne supprimez pas une observation uniquement parce qu’elle ne correspond pas au résultat souhaité.'],
['Portée','La conclusion doit rester compatible avec le terrain et la méthode.','Un résultat obtenu dans une organisation ne s’applique pas automatiquement à toutes les organisations. Précisez contexte, données et limites. La contribution peut proposer une explication utile et des prolongements, sans prétendre démontrer une loi générale. Les références et traitements doivent permettre au lecteur de suivre le raisonnement.']],
'Deux entretiens indiquent que le délai de traitement s’est amélioré. Un tableau mensuel montre une dégradation. Les entretiens portent sur un service et le tableau sur toute l’organisation. Une hypothèse initiale attribuait l’amélioration à un nouvel outil.',[
['Quelle vérification précède une conclusion ?','Comparer périodes, périmètres et conventions de mesure avant de déclarer les sources contradictoires sur le même objet.'],
['Quel risque méthodologique faut-il éviter ?','Retenir seulement les entretiens favorables à l’hypothèse et écarter le tableau sans examen : un biais de confirmation.'],
['Quelle conclusion est proportionnée ?','Présenter les observations selon leur périmètre et les limites ; approfondir la comparaison avant d’attribuer un effet général au nouvel outil.']],[PROGRAM_COMM()]),
});
function SOURCES_EN(){return ['Business English, British Council','https://learnenglish.britishcouncil.org/business-english'];}
function PROGRAM_COMM(){return ['Programmes officiels DCG et DSCG','https://www.enseignementsup-recherche.gouv.fr/fr/bo/2025/Hebdo32/MENS2523324A'];}
export const SYNTHESIS_COURSES=Object.fromEntries(Object.entries(SYNTHESIS_DATA).map(([id,data])=>{
 const points=data.concepts.map(([title,claim,explanation],i)=>point(title,claim+'\n\n'+explanation,id+' : '+data.title+'\nQuel raisonnement correspond à « '+title+' » ?',claim,...data.concepts.filter((_,j)=>j!==i).map(p=>p[1])));
 const c=course('dossier-synthese',data.title,data.intro,data.method,['Les notions fondamentales de cette matière.'],['Ne pas transformer une hypothèse du dossier en règle générale.','Distinguer résultat obtenu, preuve disponible et limite de la conclusion.'],points,data.context,data.questions,data.sources);
 return [id,[c]];
}));
